"use client";

import { useState } from "react";
import { Order, Customer, OrderStatus } from "@/core/api";

import Link from "next/link";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";

interface OrdersTableProps {
  orders: Order[];
  customers: Customer[];
}

export function OrdersTable({ orders, customers }: OrdersTableProps) {
  const [filterStatus, setFilterStatus] = useState<OrderStatus | "all">("all");
  const [search, setSearch] = useState("");

  const getCustomerName = (customerId: string) => {
    return customers.find((c) => c.id === customerId)?.name || "Unknown";
  };

  const filteredOrders = orders.filter((order) => {
    const matchesStatus =
      filterStatus === "all" || order.status === filterStatus;
    const customerName = (order.user_id ? getCustomerName(order.user_id) : order.guest_info?.fullName || "Guest").toLowerCase();
    const orderId = order.id.toLowerCase();
    const matchesSearch =
      customerName.includes(search.toLowerCase()) ||
      orderId.includes(search.toLowerCase());
    return matchesStatus && matchesSearch;
  });

  const getStatusStyles = (status: OrderStatus) => {
    switch (status) {
      case "pending":
        return "bg-yellow-100 text-yellow-700 hover:bg-yellow-100 border-yellow-200";
      case "paid":
      case "processing":
        return "bg-blue-100 text-blue-700 hover:bg-blue-100 border-blue-200";
      case "shipped":
        return "bg-purple-100 text-purple-700 hover:bg-purple-100 border-purple-200";
      case "delivered":
        return "bg-green-100 text-green-700 hover:bg-green-100 border-green-200";
      case "cancelled":
        return "bg-red-100 text-red-700 hover:bg-red-100 border-red-200";
      default:
        return "bg-gray-100 text-gray-700 hover:bg-gray-100 border-gray-200";
    }
  };

  const getStatusLabel = (status: OrderStatus) => {
    switch (status) {
      case "pending":
        return "Pending";
      case "paid":
        return "Paid";
      case "processing":
        return "Processing";
      case "shipped":
        return "Shipped";
      case "delivered":
        return "Completed";
      case "cancelled":
        return "Cancelled";
      default:
        return (status as string).replace(/_/g, " ");
    }
  };

  return (
   <></>
  );
}
