import { fetchClient } from "../../client";

export type OrderStatus = 'pending' | 'paid' | 'processing' | 'shipped' | 'delivered' | 'cancelled';

export interface OrderItem {
  id: string;
  name: string;
  quantity: number;
  price: number;
  image: string;
  product: any;
  selected_option?: string;
  price_at_time: number;
}

export interface Order {
  id: string;
  user_id: string | null;
  guest_info: any | null;
  status: OrderStatus;
  payment_method: string | null;
  subtotal: number;
  delivery_fee: number;
  total_amount: number;
  items: any[];
  delivery: any | null;
  created_at: string;
  updated_at: string;
}

export const getOrders = async (skip: number = 0, limit: number = 100): Promise<Order[]> => {
  return fetchClient<Order[]>(`/admin/orders?skip=${skip}&limit=${limit}`);
};

export const getOrderById = async (id: string): Promise<Order> => {
  return fetchClient<Order>(`/admin/orders/${id}`);
};

export const updateOrderStatus = async (id: string, status: string): Promise<Order> => {
  return fetchClient<Order>(`/admin/orders/${id}/status?status=${status}`, {
    method: "PUT"
  });
};
